#!/usr/bin/env node

/**
 * 🧠 Kim-Project-CLI Memo API
 * Claude Code 메모 시스템 연동
 *
 * 프로젝트별 메모 저장/조회/동기화
 */

const express = require('express');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const app = express();
app.use(express.json());

const PORT = process.env.PORT || 40012;
const MEMO_DIR = path.join(process.env.HOME, 'kim-project-cli', 'memo');
const INDEX_FILE = path.join(MEMO_DIR, 'index.json');
const CONFIG_FILE = path.join(process.env.HOME, 'kim-project-cli', 'memo-config.json');

// 초기화
function initMemoSystem() {
  if (!fs.existsSync(MEMO_DIR)) {
    fs.mkdirSync(MEMO_DIR, { recursive: true });
    console.log('✅ memo/ 디렉토리 생성');
  }

  if (!fs.existsSync(INDEX_FILE)) {
    fs.writeFileSync(INDEX_FILE, JSON.stringify({ memos: [] }, null, 2));
    console.log('✅ index.json 초기화');
  }

  if (!fs.existsSync(CONFIG_FILE)) {
    fs.writeFileSync(CONFIG_FILE, JSON.stringify({
      version: '1.0',
      auto_sync: true,
      sync_interval: 3600000,
      categories: ['memory', 'note', 'insight', 'bug', 'todo']
    }, null, 2));
    console.log('✅ memo-config.json 초기화');
  }
}

initMemoSystem();

// 유틸: 프로젝트 메모 디렉토리
function getProjectMemoDir(projectName) {
  return path.join(MEMO_DIR, projectName);
}

// 유틸: 메모 ID 생성
function generateMemoId() {
  return crypto.randomBytes(16).toString('hex');
}

// 유틸: 인덱스 읽기
function readIndex() {
  try {
    return JSON.parse(fs.readFileSync(INDEX_FILE, 'utf-8'));
  } catch (e) {
    return { memos: [] };
  }
}

// 유틸: 인덱스 쓰기
function writeIndex(data) {
  fs.writeFileSync(INDEX_FILE, JSON.stringify(data, null, 2));
}

// 헬스 체크
app.get('/health', (req, res) => {
  res.json({ status: 'ok', service: 'memo-api', version: '1.0' });
});

/**
 * 📝 메모 생성
 * POST /api/memo/:project
 */
app.post('/api/memo/:project', (req, res) => {
  try {
    const { project } = req.params;
    const { category, title, content, tags = [], importance = 3, author = 'claude' } = req.body;

    if (!category || !title || !content) {
      return res.status(400).json({ error: 'category, title, content 필수' });
    }

    const memoId = generateMemoId();
    const now = new Date().toISOString();
    const projectDir = getProjectMemoDir(project);

    if (!fs.existsSync(projectDir)) {
      fs.mkdirSync(projectDir, { recursive: true });
    }

    const memo = {
      id: memoId,
      project_name: project,
      category,
      title,
      content,
      tags,
      importance,
      author,
      created_at: now,
      updated_at: now
    };

    // 메모 파일 저장
    const memoryFile = path.join(projectDir, 'memory.json');
    let memos = [];
    if (fs.existsSync(memoryFile)) {
      memos = JSON.parse(fs.readFileSync(memoryFile, 'utf-8'));
    }
    memos.push(memo);
    fs.writeFileSync(memoryFile, JSON.stringify(memos, null, 2));

    // 인덱스 업데이트
    const index = readIndex();
    if (!index.memos.find(m => m.id === memoId)) {
      index.memos.push({
        id: memoId,
        project: project,
        title: title,
        category: category,
        created_at: now
      });
      writeIndex(index);
    }

    res.status(201).json({
      success: true,
      memo: memo
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

/**
 * 🔍 메모 조회
 * GET /api/memo/:project
 */
app.get('/api/memo/:project', (req, res) => {
  try {
    const { project } = req.params;
    const { category, tag, sort = 'created_at' } = req.query;

    const projectDir = getProjectMemoDir(project);
    const memoryFile = path.join(projectDir, 'memory.json');

    if (!fs.existsSync(memoryFile)) {
      return res.json({ project: project, memos: [] });
    }

    let memos = JSON.parse(fs.readFileSync(memoryFile, 'utf-8'));

    // 필터링
    if (category) {
      memos = memos.filter(m => m.category === category);
    }
    if (tag) {
      memos = memos.filter(m => m.tags.includes(tag));
    }

    // 정렬
    if (sort === 'importance') {
      memos.sort((a, b) => b.importance - a.importance);
    } else if (sort === 'updated_at') {
      memos.sort((a, b) => new Date(b.updated_at) - new Date(a.updated_at));
    } else {
      memos.sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
    }

    res.json({
      project: project,
      count: memos.length,
      memos: memos
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

/**
 * 📋 메모 수정
 * PUT /api/memo/:project/:id
 */
app.put('/api/memo/:project/:id', (req, res) => {
  try {
    const { project, id } = req.params;
    const { title, content, category, tags, importance } = req.body;

    const projectDir = getProjectMemoDir(project);
    const memoryFile = path.join(projectDir, 'memory.json');

    if (!fs.existsSync(memoryFile)) {
      return res.status(404).json({ error: '메모 없음' });
    }

    let memos = JSON.parse(fs.readFileSync(memoryFile, 'utf-8'));
    const memoIdx = memos.findIndex(m => m.id === id);

    if (memoIdx === -1) {
      return res.status(404).json({ error: '메모 ID 없음' });
    }

    // 업데이트
    if (title) memos[memoIdx].title = title;
    if (content) memos[memoIdx].content = content;
    if (category) memos[memoIdx].category = category;
    if (tags) memos[memoIdx].tags = tags;
    if (importance) memos[memoIdx].importance = importance;
    memos[memoIdx].updated_at = new Date().toISOString();

    fs.writeFileSync(memoryFile, JSON.stringify(memos, null, 2));

    res.json({
      success: true,
      memo: memos[memoIdx]
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

/**
 * 🗑️ 메모 삭제
 * DELETE /api/memo/:project/:id
 */
app.delete('/api/memo/:project/:id', (req, res) => {
  try {
    const { project, id } = req.params;

    const projectDir = getProjectMemoDir(project);
    const memoryFile = path.join(projectDir, 'memory.json');

    if (!fs.existsSync(memoryFile)) {
      return res.status(404).json({ error: '메모 없음' });
    }

    let memos = JSON.parse(fs.readFileSync(memoryFile, 'utf-8'));
    const before = memos.length;
    memos = memos.filter(m => m.id !== id);

    if (memos.length === before) {
      return res.status(404).json({ error: '메모 ID 없음' });
    }

    fs.writeFileSync(memoryFile, JSON.stringify(memos, null, 2));

    // 인덱스 업데이트
    const index = readIndex();
    index.memos = index.memos.filter(m => m.id !== id);
    writeIndex(index);

    res.json({ success: true, message: '메모 삭제됨' });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

/**
 * 🔎 전체 검색
 * GET /api/memo/search?q=keyword
 */
app.get('/api/memo/search', (req, res) => {
  try {
    const { q } = req.query;

    if (!q) {
      return res.status(400).json({ error: 'q (검색어) 필수' });
    }

    const results = [];
    const projects = fs.readdirSync(MEMO_DIR)
      .filter(f => fs.statSync(path.join(MEMO_DIR, f)).isDirectory());

    projects.forEach(project => {
      const memoryFile = path.join(MEMO_DIR, project, 'memory.json');
      if (!fs.existsSync(memoryFile)) return;

      const memos = JSON.parse(fs.readFileSync(memoryFile, 'utf-8'));
      memos.forEach(memo => {
        if (memo.title.includes(q) || memo.content.includes(q)) {
          results.push({
            ...memo,
            project: project
          });
        }
      });
    });

    res.json({
      query: q,
      count: results.length,
      results: results
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

/**
 * 📊 통계
 * GET /api/memo/stats
 */
app.get('/api/memo/stats', (req, res) => {
  try {
    const index = readIndex();
    const byCategory = {};
    const byProject = {};

    index.memos.forEach(memo => {
      byCategory[memo.category] = (byCategory[memo.category] || 0) + 1;
      byProject[memo.project] = (byProject[memo.project] || 0) + 1;
    });

    res.json({
      total: index.memos.length,
      by_category: byCategory,
      by_project: byProject,
      projects: Object.keys(byProject).length
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// 서버 시작
app.listen(PORT, () => {
  console.log(`\n🧠 Memo API 서버`);
  console.log(`📌 포트: ${PORT}`);
  console.log(`📁 메모 저장소: ${MEMO_DIR}`);
  console.log(`\n📚 엔드포인트:`);
  console.log(`  POST   /api/memo/:project`);
  console.log(`  GET    /api/memo/:project`);
  console.log(`  PUT    /api/memo/:project/:id`);
  console.log(`  DELETE /api/memo/:project/:id`);
  console.log(`  GET    /api/memo/search?q=keyword`);
  console.log(`  GET    /api/memo/stats\n`);
});

process.on('SIGINT', () => {
  console.log('\n⛔ 메모 API 종료');
  process.exit(0);
});

